import { useId, useRef } from 'react';
import type { KeyboardEvent } from 'react';
import { cx } from '@/lib/cx';
import './card-tabs.css';

/**
 * B8 · CardTabs — in-card filters that change content IN PLACE (unlike
 * BandSubTabs, which navigate). Two honest modes, never mixed:
 * - mode="tabs":    real tablist/tab/tabpanel with arrow keys (client panels)
 * - mode="filters": buttons with aria-pressed (server-side filtering)
 */
export interface CardTab {
  id: string;
  label: string;
  /** Optional mono count shown after the label. */
  count?: number;
}

export interface CardTabsProps {
  tabs: CardTab[];
  active: string;
  onChange: (id: string) => void;
  mode?: 'tabs' | 'filters';
  /** Ties tabs to their panel: panel must carry id={`${idBase}-panel`}
      and aria-labelledby={`${idBase}-tab-${active}`} in tabs mode. */
  idBase?: string;
  className?: string;
}

export function CardTabs({ tabs, active, onChange, mode = 'tabs', idBase, className }: CardTabsProps) {
  const autoId = useId();
  const base = idBase ?? autoId;
  const listRef = useRef<HTMLDivElement>(null);

  function onKeyDown(e: KeyboardEvent) {
    if (mode !== 'tabs') return;
    const idx = tabs.findIndex((t) => t.id === active);
    let next = -1;
    if (e.key === 'ArrowRight') next = (idx + 1) % tabs.length;
    if (e.key === 'ArrowLeft') next = (idx - 1 + tabs.length) % tabs.length;
    if (e.key === 'Home') next = 0;
    if (e.key === 'End') next = tabs.length - 1;
    if (next >= 0) {
      e.preventDefault();
      onChange(tabs[next].id);
      const buttons = listRef.current?.querySelectorAll<HTMLButtonElement>('button');
      buttons?.[next]?.focus();
    }
  }

  return (
    <div
      ref={listRef}
      className={cx('sv-cardtabs', className)}
      role={mode === 'tabs' ? 'tablist' : undefined}
      onKeyDown={onKeyDown}
    >
      {tabs.map((tab) => {
        const isActive = tab.id === active;
        const shared = {
          key: tab.id,
          className: cx('sv-cardtabs__tab', isActive && 'sv-cardtabs__tab--active'),
          onClick: () => onChange(tab.id),
          children: (
            <>
              {tab.label}
              {tab.count !== undefined && (
                <span className="sv-cardtabs__count sv-mono sv-num">{tab.count}</span>
              )}
            </>
          ),
        };
        return mode === 'tabs' ? (
          <button
            type="button"
            {...shared}
            role="tab"
            id={`${base}-tab-${tab.id}`}
            aria-selected={isActive}
            aria-controls={`${base}-panel`}
            tabIndex={isActive ? 0 : -1}
          />
        ) : (
          <button type="button" {...shared} aria-pressed={isActive} />
        );
      })}
    </div>
  );
}

/* B8 · CardTabs */

@layer sv-components {
  .sv-cardtabs {
    display: flex;
    gap: var(--sv-s5);
    padding: 0 18px;
    border-bottom: 1px solid var(--sv-line);
  }

  .sv-cardtabs__tab {
    position: relative;
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: var(--sv-s2) 0 10px;
    border: 0;
    background: transparent;
    font-size: 13.5px;
    font-weight: 600;
    color: var(--sv-ink-soft);
    cursor: pointer;
    transition: color var(--sv-t-fast);
  }

  .sv-cardtabs__tab:hover {
    color: var(--sv-ink);
  }

  .sv-cardtabs__tab--active {
    color: var(--sv-seed-text);
  }

  /* 2px seed underline sitting ON the card hairline */
  .sv-cardtabs__tab--active::after {
    content: '';
    position: absolute;
    left: 0;
    right: 0;
    bottom: -1px;
    height: 2px;
    background: var(--sv-seed);
  }

  .sv-cardtabs__count {
    color: var(--sv-ink-faint);
    letter-spacing: 0.06em;
  }
}
